def execute(arguments):
    """
    环境变量操作

    参数:
        arguments (dict): 包含以下字段
            - operation (str): 操作类型，"get"（获取，默认）、"set"（设置）、"delete"（删除）
            - name (str): 环境变量名，get/set/delete 操作必填
            - value (str): 环境变量值，set 操作必填

    返回:
        dict: 包含操作结果的字典
            - success (bool): 是否成功
            - exists (bool): 变量是否存在（get单个变量时）
            - name (str): 变量名
            - value (str): 变量值
            - variables (dict): 所有环境变量（get未指定name时）
            - action (str): 执行的操作
            - error (str): 错误信息（失败时）
    """
    import os

    operation = arguments.get("operation", "get")
    name = arguments.get("name", "")
    value = arguments.get("value", "")

    try:
        if operation == "get":
            if name:
                val = os.environ.get(name)
                if val is None:
                    return {"success": True, "exists": False, "name": name, "value": None}
                return {"success": True, "exists": True, "name": name, "value": val}
            else:
                return {"success": True, "variables": dict(os.environ)}

        elif operation == "set":
            if not name:
                return {"success": False, "error": "请提供环境变量名称"}
            os.environ[name] = str(value)
            return {"success": True, "name": name, "value": str(value), "action": "set"}

        elif operation == "delete":
            if not name:
                return {"success": False, "error": "请提供环境变量名称"}
            if name in os.environ:
                del os.environ[name]
                return {"success": True, "name": name, "action": "deleted"}
            else:
                return {"success": False, "error": f"环境变量不存在: {name}"}

        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except Exception as e:
        return {"success": False, "error": f"操作失败: {str(e)}"}
